[TestClass]
public class PerformanceTests
{
    public TestContext TestContext { get; set; } = null!;

    [TestCleanup]
    public void CheckTimingThreshold()
    {
        var method = GetType().GetMethod(TestContext.TestName!);
        var attr = method?.GetCustomAttributes(typeof(TimedTestMethodAttribute), false);
        if (attr is { Length: > 0 })
        {
            var timed = (TimedTestMethodAttribute)attr[0];
            var duration = TestContext.TestRunResultFiles; // not available directly
            // TestContext doesn't expose duration, so we rely on the Stopwatch approach below.
        }
    }

    [TimedTestMethod(warningThresholdMs: 1000)]
    [Timeout(Timeout.Infinite)]
    public void ProcessLargeDataSet_CompletesInTime()
    {
        Assert.IsTrue(true);
    }

    [TimedTestMethod]
    public void QuickCalculation_IsFast()
    {
        Assert.IsTrue(true);
    }

    [TestMethod]
    [Timeout(Timeout.Infinite)]
    public void LongRunningIntegration_NeverTimesOut()
    {
        Assert.IsTrue(true);
    }
}

